func:
// 엣지 게이트웨이: 필드버스 값(여기서는 msg.payload 또는 예시 값) → 메타팩토리 센서 묶음(metafactory/sensor-batch/1.0)
// 실제 장비: 앞단을 node-red-contrib-modbus 'Modbus-Read' · IO-Link 마스터(IoT 포트 MQTT/REST) 노드로 바꾼다
const now = Date.now() * 1000;   // 호스트 시계 = PTP(phc2sys)로 맞춘 시계 (µs)
const cell = env.get('CELL') || 'DT_ASSY', zone = env.get('ZONE') || 'main';
const src = Array.isArray(msg.payload) ? msg.payload : [ { s: `SN-${cell.replace('_','')}-VIB`, m: 'vrms', v: 1.2 + Math.random() * 0.2, u: 'mm/s' }, { s: `SN-${cell.replace('_','')}-CURRENT`, m: 'irms', v: 8 + Math.random(), u: 'A' } ];
const seq = (context.get('seq') || 0) + 1; context.set('seq', seq);
msg.topic = `metafactory/sensors/v1/${zone}/${cell}`;
msg.payload = { spec: 'metafactory/sensor-batch/1.0', zone, cell, edge: `EDGE-${zone.toUpperCase()}-${cell}`, gateway: env.get('GATEWAY') || 'GW-MAIN-A', seq,
  clock: { reference: 'PTP IEEE 1588-2019' }, hops: { edge: now, gateway: now },
  readings: src.map((r) => ({ ...r, ts: r.ts || now })) };
return msg;
